package dev.zomboid.firstaid;
import java.util.*;
public final class Assist {
 static final Map<Object,Attempt> attempts=new WeakHashMap<>();static Object completing;
 record Attempt(Object target,long start){}
 public static Object model(Object p){return R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"getDamageModel",p);}
 static long time(Object p){return ((Number)R.call(R.call(p,"level"),"getGameTime")).longValue();}
 static void message(Object p,String s){R.call(p,"displayClientMessage",R.call(R.type("net.minecraft.network.chat.Component"),"literal",s),true);}
 public static void hearts(Object p){Object a=R.call(p,"getAttribute",R.get(R.type("net.minecraft.world.entity.ai.attributes.Attributes"),"MAX_HEALTH"));if(a==null)return;Object id=R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse","firstaid:zomboid_extra_hearts");if(R.call(a,"getModifier",id)==null)R.call(a,"addPermanentModifier",R.make("net.minecraft.world.entity.ai.attributes.AttributeModifier",id,6d,R.get(R.type("net.minecraft.world.entity.ai.attributes.AttributeModifier$Operation"),"ADD_VALUE")));}
 static Object defib(Object p){Object handler=R.type("ichttt.mods.firstaid.common.EventHandler");for(String hand:List.of("MAIN_HAND","OFF_HAND")){Object stack=R.call(p,"getItemInHand",R.get(R.type("net.minecraft.world.InteractionHand"),hand));if(R.yes(R.call(handler,"isDefibrillator",stack)))return stack;}return null;}
 public static void self(Object p){Object m=model(p);if(m==null||!Revival.active(m)||defib(p)==null||attempts.containsKey(p))return;attempts.put(p,new Attempt(p,time(p)));message(p,"Desfibrilador · reanimación en 8 segundos");}
 public static boolean interact(Object event){Object p=R.call(event,"getEntity"),target=R.call(event,"getTarget");if(!R.type("net.minecraft.world.entity.player.Player").isInstance(target))return false;Object m=model(target);if(m==null||!Revival.active(m))return false;R.call(event,"setCanceled",true);if(R.yes(R.call(R.call(p,"level"),"isClientSide")))return true;if(p==target||!R.yes(R.call(p,"isAlive"))||R.yes(R.call(model(p),"isUnconscious")))return true;if(R.num(R.call(p,"distanceToSqr",target))>9)return true;Attempt old=attempts.get(p);if(old==null||old.target()!=target)attempts.put(p,new Attempt(target,time(p)));message(p,"Reanimando · 8 segundos · permanece cerca");return true;}
 public static void tick(Object event){Object p=R.call(event,"getEntity");if(R.yes(R.call(R.call(p,"level"),"isClientSide")))return;Object own=model(p);if(own!=null&&R.yes(R.call(p,"isAlive")))Revival.clock(own,p);Attempt a=attempts.get(p);if(a==null)return;Object t=a.target(),m=model(t);if(!R.yes(R.call(p,"isAlive"))||!R.yes(R.call(t,"isAlive"))||R.yes(R.call(t,"isRemoved"))||R.call(t,"level")!=R.call(p,"level")||R.num(R.call(p,"distanceToSqr",t))>9||m==null||!Revival.active(m)||(p!=t&&R.yes(R.call(model(p),"isUnconscious")))||(p==t&&defib(p)==null)){attempts.remove(p);message(p,"Reanimación interrumpida");return;}long elapsed=time(p)-a.start();if(elapsed<0){attempts.remove(p);return;}if(elapsed%10==0){R.call(p,"swing",R.get(R.type("net.minecraft.world.InteractionHand"),"MAIN_HAND"));message(p,"Reanimando ["+"|".repeat((int)Math.min(16,elapsed/10))+"·".repeat((int)Math.max(0,16-elapsed/10))+"] "+Math.min(100,elapsed*100/160)+"%");}if(elapsed%40==0)sound(p,"revive_work");if(elapsed>=160){attempts.remove(p);if(p==t){Object stack=defib(p);R.call(stack,"hurtAndBreak",1,p,R.get(R.type("net.minecraft.world.entity.EquipmentSlot"),R.call(p,"getMainHandItem")==stack?"MAINHAND":"OFFHAND"));}finish(m,t);sound(t,"revive_complete");message(p,"Reanimación completada · necesita curarse");}}
 public static boolean allowed(Object m){return !Revival.active(m)||completing==m;}
 static void finish(Object m,Object p){completing=m;try{if(!R.yes(R.call(m,"rescueFromCriticalState",p,null,false)))return;float ratio=6f/((Number)R.call(p,"getMaxHealth")).floatValue();for(Object part:ZeroParts.parts(m))R.set(part,"currentHealth",Math.min(((Number)R.call(part,"getMaxHealth")).floatValue(),ratio*((Number)R.call(part,"getMaxHealth")).floatValue()));R.call(R.call(p,"getPersistentData"),"putLong","FABleedGraceUntil",time(p)+400);R.call(m,"syncVanillaHealth",p);R.call(m,"scheduleResync");R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"syncDamageModel",p);message(p,"Reanimado · tienes 20 segundos para vendarte");}finally{completing=null;}}
 public static boolean bleedingGrace(Object p){return time(p)<((Number)R.call(R.call(p,"getPersistentData"),"getLong","FABleedGraceUntil")).longValue();}
 public static Boolean damage(Object p,Object source,float amount){if(amount>0)attempts.remove(p);Object m=model(p);if(m==null||!Revival.active(m)||Revival.bypass(source))return null;Object attacker=R.call(source,"getEntity"),direct=R.call(source,"getDirectEntity");if(amount>0&&(attacker!=null||direct!=null)){Object tag=R.call(p,"getPersistentData");int hits=((Number)R.call(tag,"getInt","FAFinishHits")).intValue()+1;R.call(tag,"putInt","FAFinishHits",hits);attempts.entrySet().removeIf(e->e.getKey()==p||e.getValue().target()==p);if(hits>=3){R.set(m,"criticalConditionActive",false);R.call(m,"clearUnconsciousState");R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"killPlayerDirectly",p,source);}}return Boolean.FALSE;}
 static void sound(Object p,String name){try{Object id=R.call(R.type("net.minecraft.resources.ResourceLocation"),"parse","firstaid:"+name),s=R.call(R.type("net.minecraft.sounds.SoundEvent"),"createVariableRangeEvent",id);R.call(R.call(p,"level"),"playSound",null,R.call(p,"blockPosition"),s,R.get(R.type("net.minecraft.sounds.SoundSource"),"PLAYERS"),.65f,1f);}catch(Exception e){R.warn("revival sound",e);}}
}
